"""Frozen release-package GPU comparison; input loading and warmup precede timing."""
import vapoursynth as vs
import numpy as np
import hashlib,json,os,pathlib
core=vs.core;core.num_threads=int(threads);core.max_cache_size=512
if hasattr(core,'dsmvc'):raise RuntimeError('unexpected autoloaded dsmvc')
p=pathlib.Path(plugin).resolve();core.std.LoadPlugin(path=str(p))
mapped=sorted({line.split()[-1] for line in pathlib.Path('/proc/self/maps').read_text().splitlines() if str(p) in line})
assert mapped==[str(p)],mapped
identity=dict(plugin_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),mapped=mapped,vs=str(vs.__version__),threads=int(threads),source_fills_inside_timer=0,rhs_policy={k:os.environ.get(k,'automatic') for k in ['DSMVC_CUDA_SPLIT_RHS','DSMVC_VULKAN_SPLIT_RHS']})
print('BINARY_IDENTITY='+json.dumps(identity),flush=True)
count=int(frames);warm=128 if scenario=='hot' else 64
raw=pathlib.Path(__file__).with_name('frame12493.f32').read_bytes()
assert hashlib.sha256(raw).hexdigest()=='d50727fbfe6a6cb47eee915d5e92372292c41f7280d4d80d8db37312817e36bd'
blank=core.std.BlankClip(width=1920,height=1080,length=1,format=vs.GRAYS)
fixed=blank.get_frame(0).copy();np.copyto(np.asarray(fixed[0]),np.frombuffer(raw,dtype=np.float32).reshape(1080,1920))
one=core.std.ModifyFrame(blank,blank,lambda n,f:fixed);one.get_frame(0);source=one.std.Loop(times=count+warm)
heights=[(7000+round(i*2799/(count-1)))/10 for i in range(count)]
heights[round((951.5-700)/279.9*(count-1))]=951.5
names={'bilinear':'Debilinear','bicubic':'Debicubic','spline64':'Despline64'}
def geometry(height):
 width=1920/1080*height;bw=round(1920/1080*1000);ow=bw-2*int((bw-width)/2);oh=1000-2*int((1000-height)/2)
 return dict(width=ow,height=oh,src_width=width,src_height=height,src_left=(ow-width)/2,src_top=(oh-height)/2)
def descale(height):
 args=geometry(height);args.update(backend=backend,f64mode=1,blur=1.0,padding=3)
 if kernel.startswith('lanczos'):return core.dsmvc.Delanczos(source,taps=int(kernel[7:]),**args)
 if kernel=='bicubic':args.update(b=0.0,c=.5)
 return getattr(core.dsmvc,names[kernel])(source,**args)
def reconstruct(height):
 clip=descale(height);args=geometry(height);args.pop('width');args.pop('height');name=kernel.capitalize()
 if kernel.startswith('lanczos'):name='Lanczos';args['filter_param_a']=int(kernel[7:])
 if kernel=='bicubic':args.update(filter_param_a=0.0,filter_param_b=.5)
 return getattr(core.resize,name)(clip,1920,1080,**args)
if scenario=='hot':
 output=descale(951.5)
 for n in range(warm):output.get_frame(n)
else:
 assert scenario=='scan'
 warm_clip=reconstruct(810.0)
 for n in range(warm):warm_clip.get_frame(n)
 driver=source.std.Trim(0,count-1)
 reconstructed=core.std.FrameEval(driver,lambda n:reconstruct(heights[n]))
 output=core.std.Expr([reconstructed,driver],['x y - abs dup 0.015 > swap 0 ?']).std.CropRel(5,5,5,5).std.PlaneStats()
if globals().get('proof',''):
 indices=list(range(warm,warm+4)) if scenario=='hot' else sorted({round(i*(count-1)/31) for i in range(32)})
 if int(threads)==1:observed=[(n,output.get_frame(n)) for n in indices]
 else:
  futures=[(n,output.get_frame_async(n)) for n in indices];observed=[(n,f.result()) for n,f in futures]
 rows=[]
 for n,f in observed:
  data=np.asarray(f[0]);assert np.isfinite(data).all()
  rows.append(dict(n=n,height=951.5 if scenario=='hot' else heights[n],shape=list(data.shape),sha256=hashlib.sha256(data.tobytes(order='C')).hexdigest(),stats={k:float(f.props[k]) for k in ['PlaneStatsAverage','PlaneStatsMin','PlaneStatsMax'] if k in f.props}))
 pathlib.Path(proof).write_text(json.dumps(rows,indent=2)+'\n')
output.set_output(0)
